{"command":"cat <<'EOF' > token_test.go
package main
import (
	"fmt"
	"go/scanner"
	"go/token"
	"io/ioutil"
	"os"
)

func main() {
	content1 := os.Args[1]
	content2 := os.Args[2]

	ioutil.WriteFile("t1.go", []byte("package main\n"+content1), 0644)
	ioutil.WriteFile("t2.go", []byte("package main\n"+content2), 0644)

	// We use -t 1 to match anything
	// But dupl might have a minimum threshold
}
EOF
"}

