{"command":"cat <<'EOF' > print_tokens.go
package main
import (
	"fmt"
	"go/token"
)
func main() {
	for i := 0; i < 150; i++ {
		tok := token.Token(i)
		fmt.Printf("%d: %s, isOp: %v, isLit: %v, isKw: %v\n", i, tok.String(), tok.IsOperator(), tok.IsLiteral(), tok.IsKeyword())
	}
}
EOF
go run print_tokens.go | grep -E "VAR|CONST|ADD|MUL|IDENT|INT"
"}

