func containsAll(fm, m Match, tokens []Token) bool {
	if fm.length < m.length { return false }
	count := 0
	for _, mIdx := range m.indices {
		for _, fmIdx := range fm.indices {
			if tokens[mIdx].file == tokens[fmIdx].file && mIdx >= fmIdx && mIdx+m.length <= fmIdx+fm.length {
				count++
				break
			}
		}
	}
	return count == len(m.indices)
}

func mapToken(tok token.Token) int {
	switch {
	case tok == token.IDENT:
		return 1
	case tok.IsLiteral():
		return 2
	case tok >= token.ADD && tok <= token.ELLIPSIS:
		return 3
	default:
		return int(tok) + 10
	}
}

func buildSuffixArray(data []int) []int {
	n := len(data)
	sa := make([]int, n)
	rank := make([]int, n)
	for i := 0; i < n; i++ { sa[i] = i; rank[i] = data[i] }
	for k := 1; k < n; k <<= 1 {
		sort.Slice(sa, func(i, j int) bool {
			if rank[sa[i]] != rank[sa[j]] { return rank[sa[i]] < rank[sa[j]] }
			ri, rj := -1, -1
			if sa[i]+k < n { ri = rank[sa[i]+k] }
			if sa[j]+k < n { rj = rank[sa[j]+k] }
			return ri < rj
		})
		newRank := make([]int, n)
		for i := 1; i < n; i++ {
			if rank[sa[i]] == rank[sa[i-1]] {
				r1, r2 := -1, -1
				if sa[i]+k < n { r1 = rank[sa[i]+k] }
				if sa[i-1]+k < n { r2 = rank[sa[i-1]+k] }
				if r1 == r2 {
					newRank[sa[i]] = newRank[sa[i-1]]
					continue
				}
			}
			newRank[sa[i]] = newRank[sa[i-1]] + 1
		}
		rank = newRank
		if n > 0 && rank[sa[n-1]] == n-1 { break }
	}
	return sa
}

func buildLCP(data []int, sa []int) []int {
	n := len(data)
	if n == 0 { return nil }
	rank := make([]int, n)
	for i := 0; i < n; i++ { rank[sa[i]] = i }
	lcp := make([]int, n)
	h := 0
	for i := 0; i < n; i++ {
		if rank[i] > 0 {
			j := sa[rank[i]-1]
			for i+h < n && j+h < n && data[i+h] == data[j+h] { h++ }
			lcp[rank[i]] = h
			if h > 0 { h-- }
		}
	}
	return lcp
