func buildSuffixArray(data []int) []int {
	n := len(data)
	sa := make([]int, n)
	rank := make([]int, n)
	for i := 0; i < n; i++ { sa[i] = i; rank[i] = data[i] }
	for k := 1; k < n; k <<= 1 {
		sort.Slice(sa, func(i, j int) bool {
			if rank[sa[i]] != rank[sa[j]] { return rank[sa[i]] < rank[sa[j]] }
			ri, rj := -1, -1
			if sa[i]+k < n { ri = rank[sa[i]+k] }
			if sa[j]+k < n { rj = rank[sa[j]+k] }
			return ri < rj
		})
		newRank := make([]int, n)
		for i := 1; i < n; i++ {
			if rank[sa[i]] == rank[sa[i-1]] {
				r1, r2 := -1, -1
				if sa[i]+k < n { r1 = rank[sa[i]+k] }
				if sa[i-1]+k < n { r2 = rank[sa[i-1]+k] }
