func buildLCP(data []int, sa []int) []int {
	n := len(data)
	if n == 0 { return nil }
	rank := make([]int, n)
	for i := 0; i < n; i++ { rank[sa[i]] = i }
	lcp := make([]int, n)
	h := 0
	for i := 0; i < n; i++ {
		if rank[i] > 0 {
			j := sa[rank[i]-1]
			for i+h < n && j+h < n && data[i+h] == data[j+h] { h++ }
