		fmt.Fprintf(os.Stderr, "  If the given path is a file, dupl will use it regardless of\n")
		fmt.Fprintf(os.Stderr, "  the file extension. If it is a directory it will recursively\n")
		fmt.Fprintf(os.Stderr, "  search for *.go files in that directory.\n\n")
		fmt.Fprintf(os.Stderr, "  If no path is given dupl will recursively search for *.go\n")
		fmt.Fprintf(os.Stderr, "  files in the current directory.\n\n")
		fmt.Fprintf(os.Stderr, "Flags:\n")
		flag.PrintDefaults()
	}

	flag.Parse()

	var paths []string
	if files {
		content, _ := ioutil.ReadAll(os.Stdin)
		paths = strings.Fields(string(content))
	} else {
		paths = flag.Args()
	}

	if len(paths) == 0 && !files {
		paths = []string{"."}
	}

	allFiles := []string{}
	for _, path := range paths {
		path = strings.TrimSpace(path)
		if path == "" { continue }
		info, err := os.Stat(path)
		if err != nil { continue }
		if info.IsDir() {
			filepath.Walk(path, func(p string, info os.FileInfo, err error) error {
				if err != nil { return nil }
				if !vendor && (strings.HasPrefix(p, "vendor/") || strings.Contains(p, "/vendor/")) {
					if info.IsDir() { return filepath.SkipDir }
					return nil
				}
				if !info.IsDir() && strings.HasSuffix(p, ".go") {
					allFiles = append(allFiles, p)
				}
				return nil
			})
		} else {
			allFiles = append(allFiles, path)
		}
	}

	allTokens := []Token{}
	for _, file := range allFiles {
		fset := token.NewFileSet()
		content, err := ioutil.ReadFile(file)
		if err != nil { continue }
		var s scanner.Scanner
		s.Init(fset.AddFile(file, fset.Base(), len(content)), content, nil, 0)
		for {
			pos, tok, _ := s.Scan()
			if tok == token.EOF { break }
			if tok == token.SEMICOLON { continue }
			allTokens = append(allTokens, Token{
				val:  mapToken(tok),
				pos:  fset.Position(pos),
				file: file,
			})
		}
	}

	if verbose {
		log.Println("Building suffix tree")
	}

	n := len(allTokens)
	data := make([]int, n)
	for i, t := range allTokens { data[i] = t.val }

	sa := buildSuffixArray(data)
	lcp := buildLCP(data, sa)

	if verbose {
		log.Println("Searching for clones")
	}

	matches := []Match{}
	for i := 1; i < n; i++ {
		if lcp[i] >= threshold {
			length := lcp[i]
			j := i
			indices := []int{sa[i-1]}
			for j < n && lcp[j] >= length {
				indices = append(indices, sa[j])
				j++
			}
			matches = append(matches, Match{indices, length})
			i = j - 1
		}
	}

	sort.Slice(matches, func(i, j int) bool {
		return matches[i].length > matches[j].length
	})

	finalMatches := []Match{}
	for _, m := range matches {
		validIndices := []int{}
		for _, idx := range m.indices {
			if isWithinSingleFile(allTokens, idx, m.length) {
				overlap := false
				for _, vIdx := range validIndices {
					if idx < vIdx + m.length && vIdx < idx + m.length {
						overlap = true
						break
					}
				}
				if !overlap {
					validIndices = append(validIndices, idx)
				}
			}
		}
		if len(validIndices) < 2 { continue }
		m.indices = validIndices
		isSub := false
		for _, fm := range finalMatches {
			if containsAll(fm, m, allTokens) {
				isSub = true
				break
			}
		}
		if !isSub {
			finalMatches = append(finalMatches, m)
		}
	}

	sort.Slice(finalMatches, func(i, j int) bool {
		return finalMatches[i].indices[0] < finalMatches[j].indices[0]
	})

	if html {
		printHTML(allTokens, finalMatches)
	} else {
		printNormal(allTokens, finalMatches, plumbing)
	}
}

func containsAll(fm, m Match, tokens []Token) bool {
	if fm.length < m.length { return false }
	count := 0
	for _, mIdx := range m.indices {
		for _, fmIdx := range fm.indices {
			if tokens[mIdx].file == tokens[fmIdx].file && mIdx >= fmIdx && mIdx+m.length <= fmIdx+fm.length {
				count++
				break
			}
		}
	}
	return count == len(m.indices)
}

func mapToken(tok token.Token) int {
	switch {
	case tok == token.IDENT:
		return 1
	case tok.IsLiteral():
		return 2
	case tok >= token.ADD && tok <= token.ELLIPSIS:
		return 3
	default:
		return int(tok) + 10
	}
}

func buildSuffixArray(data []int) []int {
	n := len(data)
	sa := make([]int, n)
	rank := make([]int, n)
	for i := 0; i < n; i++ { sa[i] = i; rank[i] = data[i] }
	for k := 1; k < n; k <<= 1 {
		sort.Slice(sa, func(i, j int) bool {
			if rank[sa[i]] != rank[sa[j]] { return rank[sa[i]] < rank[sa[j]] }
			ri, rj := -1, -1
			if sa[i]+k < n { ri = rank[sa[i]+k] }
			if sa[j]+k < n { rj = rank[sa[j]+k] }
			return ri < rj
		})
		newRank := make([]int, n)
		for i := 1; i < n; i++ {
			if rank[sa[i]] == rank[sa[i-1]] {
				r1, r2 := -1, -1
				if sa[i]+k < n { r1 = rank[sa[i]+k] }
				if sa[i-1]+k < n { r2 = rank[sa[i-1]+k] }
				if r1 == r2 {
					newRank[sa[i]] = newRank[sa[i-1]]
					continue
				}
			}
			newRank[sa[i]] = newRank[sa[i-1]] + 1
		}
		rank = newRank
		if n > 0 && rank[sa[n-1]] == n-1 { break }
	}
	return sa
}

func buildLCP(data []int, sa []int) []int {
	n := len(data)
	if n == 0 { return nil }
	rank := make([]int, n)
	for i := 0; i < n; i++ { rank[sa[i]] = i }
	lcp := make([]int, n)
	h := 0
	for i := 0; i < n; i++ {
		if rank[i] > 0 {
			j := sa[rank[i]-1]
			for i+h < n && j+h < n && data[i+h] == data[j+h] { h++ }
			lcp[rank[i]] = h
			if h > 0 { h-- }
		}
	}
	return lcp
}

func printNormal(allTokens []Token, matches []Match, plumbing bool) {
	count := 0
	for _, m := range matches {
		indices := m.indices
		sort.Ints(indices)
		if plumbing {
			for i := 0; i < len(indices); i++ {
				for j := 0; j < len(indices); j++ {
					if i == j { continue }
					idx1, idx2 := indices[i], indices[j]
					fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n",
						allTokens[idx1].file, allTokens[idx1].pos.Line, allTokens[idx1+m.length-1].pos.Line,
						allTokens[idx2].file, allTokens[idx2].pos.Line, allTokens[idx2+m.length-1].pos.Line)
				}
			}
		} else {
			fmt.Printf("found %d clones:\n", len(indices))
			for _, idx := range indices {
				fmt.Printf("  %s:%d,%d\n", allTokens[idx].file, allTokens[idx].pos.Line, allTokens[idx+m.length-1].pos.Line)
			}
		}
		count++
	}
	if !plumbing {
		fmt.Printf("\nFound total %d clone groups.\n", count)
	}
}

func isWithinSingleFile(tokens []Token, start, length int) bool {
	if start+length > len(tokens) { return false }
	file := tokens[start].file
	for i := 1; i < length; i++ {
		if tokens[start+i].file != file { return false }
	}
	return true
}

func printHTML(allTokens []Token, matches []Match) {
	fmt.Println(`<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>`)
	for i, m := range matches {
		indices := m.indices
		sort.Ints(indices)
		fmt.Printf("<h1>#%d found %d clones</h1>\n", i+1, len(indices))
		for _, idx := range indices {
			lineStart, lineEnd := allTokens[idx].pos.Line, allTokens[idx+m.length-1].pos.Line
			fmt.Printf("<h2>%s:%d</h2>\n", allTokens[idx].file, lineStart)
			fmt.Print("<pre>")
			fmt.Print(getCode(allTokens[idx].file, lineStart, lineEnd))
			fmt.Println("</pre>")
		}
	}
}

func getCode(file string, start, end int) string {
	content, _ := ioutil.ReadFile(file)
	lines := strings.Split(string(content), "\n")
	if start < 1 { start = 1 }
	if start > len(lines) { return "" }
	if end > len(lines) { end = len(lines) }
	return strings.Join(lines[start-1:end], "\n")
}
